class Component extends DCLogic {
  componentDidMount(){ const go=()=>window.SWD?SWD.ready(()=>this.init()):setTimeout(go,30); go(); }
  init(){
    const D=SW_DEMO_DATA, CF=SW_DEMO, $=id=>document.getElementById(id), UF=SWD.UFS(), CT=CF.country, R=CF.RACA;
    SWD.page({active:'raca',lv:'BR',label:'Cor ou raça'});
    $('vstamp').innerHTML=SWD.stamp('raca'); $('src').innerHTML=SWD.srcLine(['raca']);
    $('note').innerHTML=SW2.note('Termos e categorias oficiais do IBGE. A resposta é a declarada pela pessoa entrevistada. As cores do gráfico só distinguem as categorias.');
    const st={l:SWD.q.get('u')||'BR',s:'b'};
    $('place').innerHTML=`<option value="BR">${CT.name}</option>`+UF.slice().sort((a,b)=>SWD.name(a).localeCompare(SWD.name(b))).map(u=>`<option value="${u}">${SWD.name(u)}</option>`).join('');
    $('place').onchange=e=>{st.l=e.target.value;draw()};
    SWD.seg($('sort'),R.map(r=>[r.k,r.n]),st.s,k=>{st.s=k;draw()},'Ordenar por');
    $('lg').innerHTML=R.map((r,i)=>`<span data-k="${r.k}"><i style="background:var(--c${i+1})"></i>${r.n}</span>`).join('');
    const sh=u=>{const v=D.raca[u], t=v.reduce((a,b)=>a+(b||0),0); return v.map(x=>x==null?null:x/t*100)};
    const rows=$('rows');
    const hl=k=>{ rows.classList.toggle('dim',!!k); rows.querySelectorAll('.bar i').forEach(i=>i.classList.toggle('hi',i.dataset.k===k)); };
    rows.onmouseover=e=>{const t=e.target.closest('[data-k]'); hl(t&&t.dataset.k)}; rows.onmouseleave=()=>hl(null);
    rows.onclick=e=>{const li=e.target.closest('li[data-uf]'); if(li){st.l=li.dataset.uf;draw()}};
    rows.onkeydown=e=>{ if(e.key==='Enter'||e.key===' '){const li=e.target.closest('li[data-uf]'); if(li){e.preventDefault();st.l=li.dataset.uf;draw();rows.querySelector(`li[data-uf="${st.l}"]`).focus()}} };
    const draw=()=>{ const l=st.l, si=R.findIndex(r=>r.k===st.s);
      $('place').value=l;
      SWD.cada100($('c100'),R.map((r,i)=>({k:r.k,n:r.n,v:D.raca[l][i],c:`var(--c${i+1})`})),{title:`Cada 100 pessoas em ${SWD.name(l)}`,aria:`Cor ou raça, cada 100 pessoas em ${SWD.name(l)}`});
      $('c100').insertAdjacentHTML('beforeend',`<div style="margin-top:12px">${SWD.stamp('raca')}</div>`);
      const ord=UF.slice().sort((a,b)=>sh(b)[si]-sh(a)[si]);
      rows.innerHTML=[ 'BR', ...ord ].map(u=>{const s=sh(u); return `<li data-uf="${u}" tabindex="0" class="${u===l?'on':''}" ${u==='BR'?'style="margin-bottom:8px;border-bottom:1px solid var(--line);border-radius:6px 6px 0 0"':''} aria-label="${SWD.name(u)}: ${R.map((r,i)=>`${r.n} ${SWD.num(s[i],1)}%`).join(', ')}"><span class="nm">${SWD.name(u)}</span><span class="bar" aria-hidden="true">${R.map((r,i)=>`<i data-k="${r.k}" title="${r.n}: ${SWD.num(s[i],1)}%" style="width:${s[i]}%;background:var(--c${i+1})"></i>`).join('')}</span></li>`}).join('');
    };
    draw();
  }
  renderVals(){ return {}; }
}
